hl.bind("SUPER + 5", hl.dsp.focus({ workspace = 5 }), { description = "Workspace 5" })
hl.bind("SUPER + 6", hl.dsp.focus({ workspace = 6 }), { description = "Workspace 6" })
hl.bind("SUPER + 7", hl.dsp.focus({ workspace = 7 }), { description = "Workspace 7" })
hl.bind("SUPER + 8", hl.dsp.focus({ workspace = 8 }), { description = "Workspace 8" })
hl.bind("SUPER + 9", hl.dsp.focus({ workspace = 9 }), { description = "Workspace 9" })
hl.bind("SUPER + CTRL + 1", hl.dsp.window.move({ workspace = 1 }), { description = "Move to workspace 1" })
hl.bind("SUPER + CTRL + 2", hl.dsp.window.move({ workspace = 2 }), { description = "Move to workspace 2" })
hl.bind("SUPER + CTRL + 3", hl.dsp.window.move({ workspace = 3 }), { description = "Move to workspace 3" })
hl.bind("SUPER + CTRL + 4", hl.dsp.window.move({ workspace = 4 }), { description = "Move to workspace 4" })
hl.bind("SUPER + CTRL + 5", hl.dsp.window.move({ workspace = 5 }), { description = "Move to workspace 5" })
hl.bind("SUPER + CTRL + 6", hl.dsp.window.move({ workspace = 6 }), { description = "Move to workspace 6" })
hl.bind("SUPER + CTRL + 7", hl.dsp.window.move({ workspace = 7 }), { description = "Move to workspace 7" })
hl.bind("SUPER + CTRL + 8", hl.dsp.window.move({ workspace = 8 }), { description = "Move to workspace 8" })
hl.bind("SUPER + CTRL + 9", hl.dsp.window.move({ workspace = 9 }), { description = "Move to workspace 9" })
-- 11. Window Sizing
hl.bind("SUPER + minus", hl.dsp.exec_cmd("hyprctl dispatch resizeactive -10% 0"), { repeating = true, description = "Shrink width" })
hl.bind("SUPER + equal", hl.dsp.exec_cmd("hyprctl dispatch resizeactive 10% 0"), { repeating = true, description = "Grow width" })
hl.bind("SUPER + SHIFT + minus", hl.dsp.exec_cmd("hyprctl dispatch resizeactive 0 -10%"), { repeating = true, description = "Shrink height" })
hl.bind("SUPER + SHIFT + equal", hl.dsp.exec_cmd("hyprctl dispatch resizeactive 0 10%"), { repeating = true, description = "Grow height" })
-- 12. Window Management
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ mode = "maximized" }), { description = "Maximize" })
hl.bind("SUPER + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }), { description = "Fullscreen" })
hl.bind("SUPER + C", hl.dsp.window.center(), { description = "Center window" })
hl.bind("SUPER + T", hl.dsp.group.toggle(), { description = "Toggle tabbed group" })
hl.bind("SUPER + V", hl.dsp.window.float({ action = "toggle" }), { description = "Toggle floating" })
hl.bind("SUPER + SHIFT + Q", hl.dsp.window.close(), { description = "Close window" })
-- 13. Screenshots
hl.bind("Print", hl.dsp.exec_cmd("noctalia msg screenshot-region"), { locked = true, description = "Region screenshot" })
hl.bind("CTRL + Print", hl.dsp.exec_cmd("noctalia msg screenshot-fullscreen"), { locked = true, description = "Full screen screenshot" })
hl.bind("ALT + Print", hl.dsp.exec_cmd("noctalia msg screenshot-fullscreen all"), { locked = true, description = "All monitors screenshot" })
-- 15. Session
hl.bind("SUPER + SHIFT + E", hl.dsp.exit(), { description = "Exit Hyprland" })
hl.bind("CTRL + ALT + Delete", hl.dsp.exec_cmd("noctalia msg panel-toggle session"), { description = "Session menu" })
-- 16. Mouse
hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { mouse = true, description = "Drag to move" })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true, description = "Drag to resize" })
